const http = require("http");

const server = http.createServer((req, res) => {
  res.writeHead(200, { "Content-Type": "text/plain" });
  res.end("Bonjou soti nan Node.js!");
});

server.listen(3000);
console.log("Seve ap koute sou po 3000");

const express = require("express");
const app = express();
app.use(express.json());

app.get("/bonjou/:non", (req, res) => {
  res.json({ mesaj: "Bonjou " + req.params.non });
});

app.listen(3000);

function tann(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function prensipal() {
  console.log("Komanse...");
  await tann(1000);
  console.log("1 segonn pase!");
}
prensipal();

const fs = require("fs");

const lekti = fs.createReadStream("gwo.txt", "utf8");
lekti.on("data", (moso) => {
  console.log("Moso resevwa:", moso.length, "karakte");
});
lekti.on("end", () => console.log("Fini!"));

const cluster = require("cluster");
const os = require("os");

if (cluster.isPrimary) {
  const n = os.cpus().length;
  console.log(`Met la lanse ${n} travaye`);
  for (let i = 0; i < n; i++) cluster.fork();
} else {
  require("./seve");
}

